{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "CC-292, a BTK inhibitor with a pyrimidine bis-aniline scaffold and an ether side chain, showed excellent oral bioavailability in a Phase IA human study; this is the closest analogue and supports high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "Imatinib, a pyrimidine-based kinase inhibitor with an aniline and basic amine side chain, has absolute oral bioavailability of 98% in patients, supporting high F for the query's similar oral-drug scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Pazopanib, which shares the pyrimidine-2,4-diamine and benzenesulfonamide motif with the query, has absolute oral bioavailability of 21.4%, just above the 20% threshold, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Enasidenib, a nitrogen-rich heteroaromatic oral drug, has absolute bioavailability of 57.2%, supporting high F for this class of kinase-inhibitor-like molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Bazedoxifene has only ~6% absolute bioavailability, but its low F is driven by phenolic glucuronidation; the query lacks free phenolic groups, so this contradictory evidence transfers weakly.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C11"],
      "claim": "Raloxifene has <2% absolute bioavailability due to extensive first-pass glucuronidation of phenols; the query has no phenol, limiting transferability of this low-F evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a pyrimidine-based kinase-inhibitor-like oral drug with a basic pyrrolidine-ethoxy side chain and a benzenesulfonamide, lacking the phenolic groups responsible for the low F of bazedoxifene/raloxifene. The closest analogue (CC-292) and several scaffold-related kinase inhibitors (imatinib, pazopanib, enasidenib) show high or borderline-high oral bioavailability, supporting F >=20%.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability measurement for the query molecule.",
    "CC-292 record reports 'excellent' without a numeric F value.",
    "Morgan similarities are modest (<0.4), so structural transfer is not definitive.",
    "Pazopanib's F is borderline (21.4%) and may not robustly exceed 20%."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

